1	import { createHash } from "node:crypto";
2	
3	type ResolutionDecision = "auto_merge" | "review";
4	
5	export interface ResolutionEvidence {
6		kind: string;
7		identifier: string;
8	}
9	
10	export interface ResolutionIdentity {
11		namespace: string;
12		identifier: string;
13	}
14	
15	interface ResolutionEntity {
16		id: number;
17		metadata: Record<string, unknown>;
18		/** Live identity claims that may not also exist in entity metadata. */
19		identities?: ResolutionIdentity[];
20	}
21	
22	interface EntityResolutionAssessment {
23		decision: ResolutionDecision;
24		evidence: ResolutionEvidence[];
25		policyHash: string;
26		fingerprint: string;
27		reason: string;
28	}
29	
30	interface ResolutionRule {
31		fields: string[];
32		normalizer: "email" | "phone" | "exact";
33		onMatch: ResolutionDecision;
34	}
35	
36	/**
37	 * Plural rule fields that name the same thing as their singular form, so the
38	 * human-facing reason says "email or phone" rather than listing all four.
39	 * Deliberately an explicit map: any field not listed here is printed verbatim.
40	 */
41	const RULE_FIELD_ALIASES: Record<string, string> = {
42		emails: "email",
43		phones: "phone",
44	};
45	
46	const DEFAULT_PERSON_RESOLUTION_RULES: ResolutionRule[] = [
47		{ fields: ["email"], normalizer: "email", onMatch: "review" },
48		{ fields: ["emails"], normalizer: "email", onMatch: "review" },
49		{ fields: ["phone"], normalizer: "phone", onMatch: "review" },
50		{ fields: ["phones"], normalizer: "phone", onMatch: "review" },
51	];
52	
53	function canonicalJson(value: unknown): string {
54		if (Array.isArray(value)) {
55			return `[${value.map(canonicalJson).join(",")}]`;
56		}
57		if (value && typeof value === "object") {
58			const entries = Object.entries(value as Record<string, unknown>).sort(
59				([left], [right]) => left.localeCompare(right),
60			);
61			return `{${entries
62				.map(([key, item]) => `${JSON.stringify(key)}:${canonicalJson(item)}`)
63				.join(",")}}`;
64		}
65		return JSON.stringify(value) ?? String(value);
66	}
67	
68	function digest(value: unknown): string {
69		return createHash("sha256").update(canonicalJson(value)).digest("hex");
70	}
71	
72	function readPath(metadata: Record<string, unknown>, path: string): unknown {
73		let current: unknown = metadata;
74		for (const segment of path.split(".")) {
75			if (!current || typeof current !== "object" || Array.isArray(current)) {
76				return undefined;
77			}
78			current = (current as Record<string, unknown>)[segment];
79		}
80		return current;
81	}
82	
83	function normalizeScalar(
84		value: unknown,
85		normalizer: ResolutionRule["normalizer"],
86	): string | null {
87		if (typeof value !== "string" && typeof value !== "number") return null;
88		const text = String(value).trim();
89		if (!text) return null;
90		if (normalizer === "phone") {
91			if (!/^[+()0-9 .-]+$/.test(text)) return null;
92			const digits = text.replace(/\D/g, "");
93			return digits.length >= 7 && digits.length <= 15 ? digits : null;
94		}
95		if (normalizer === "email") {
96			const email = text.toLocaleLowerCase("en-US");
97			if (email.length > 512) return null;
98			return /^[a-z0-9_%+-]+(?:\.[a-z0-9_%+-]+)*@[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$/.test(
99				email,
100			)
101				? email
102				: null;
103		}
104		return text;
105	}
106	
107	function normalizeValues(
108		value: unknown,
109		normalizer: ResolutionRule["normalizer"],
110	): string[] {
111		const values = Array.isArray(value) ? value : [value];
112		return [
113			...new Set(
114				values
115					.map((item) => normalizeScalar(item, normalizer))
116					.filter((item): item is string => item !== null),
117			),
118		].sort();
119	}
120	
121	export function readEntityResolutionRules(
122		schema: unknown,
123		options?: { entityTypeSlug?: string | null },
124	): ResolutionRule[] {
125		if (!schema || typeof schema !== "object" || Array.isArray(schema)) {
126			return options?.entityTypeSlug === "person"
127				? DEFAULT_PERSON_RESOLUTION_RULES
128				: [];
129		}
130		const config = (schema as Record<string, unknown>)["x-lobu-resolution"];
131		if (config === undefined) {
132			return options?.entityTypeSlug === "person"
133				? DEFAULT_PERSON_RESOLUTION_RULES
134				: [];
135		}
136		if (!config || typeof config !== "object" || Array.isArray(config)) return [];
137		const rules = (config as Record<string, unknown>).rules;
138		if (!Array.isArray(rules)) return [];
139		return rules.flatMap((candidate) => {
140			if (
141				!candidate ||
142				typeof candidate !== "object" ||
143				Array.isArray(candidate)
144			) {
145				return [];
146			}
147			const record = candidate as Record<string, unknown>;
148			const fields = Array.isArray(record.fields)
149				? [
150						...new Set(
151							record.fields.flatMap((field) =>
152								typeof field === "string" && field.trim().length > 0
153									? [field.trim()]
154									: [],
155							),
156						),
157					]
158				: [];
159			const normalizer = record.normalizer;
160			const onMatch = record.onMatch;
161			if (
162				fields.length === 0 ||
163				(normalizer !== "email" &&
164					normalizer !== "phone" &&
165					normalizer !== "exact") ||
166				(onMatch !== "auto_merge" && onMatch !== "review")
167			) {
168				return [];
169			}
170			return [{ fields, normalizer, onMatch }];
171		});
172	}
173	
174	export function normalizedResolutionRuleKeys(
175		entity: ResolutionEntity,
176		rule: ResolutionRule,
177	): string[] {
178		let combinations: string[][] = [[]];
179		for (const field of rule.fields) {
180			// Identity-backed connector data follows the same field policy and
181			// normalization as metadata when its namespace names that field.
182			const raw = readPath(entity.metadata, field);
183			const fromMetadata = Array.isArray(raw) ? raw : [raw];
184			const fromIdentities = (entity.identities ?? [])
185				.filter((identity) => identity.namespace === field)
186				.map((identity) => identity.identifier);
187			const values = normalizeValues(
188				[...fromMetadata, ...fromIdentities],
189				rule.normalizer,
190			);
191			if (values.length === 0) return [];
192			combinations = combinations.flatMap((prefix) =>
193				values.map((value) => [...prefix, value]),
194			);
195			if (combinations.length > 256) return [];
196		}
197		return combinations.map((parts) => parts.join("\u001f")).sort();
198	}
199	
200	/**
201	 * Decide whether a duplicate proposal is deterministic under its entity type's
202	 * schema. The caller-provided evidence is deliberately ignored: every value is
203	 * recomputed from the locked workspace entities and the versioned type policy.
204	 */
205	export function assessEntityResolution(input: {
206		metadataSchema: unknown;
207		entityTypeSlug?: string | null;
208		winner: ResolutionEntity;
209		losers: ResolutionEntity[];
210	}): EntityResolutionAssessment {
211		const rules = readEntityResolutionRules(input.metadataSchema, {
212			entityTypeSlug: input.entityTypeSlug,
213		});
214		const policyHash = digest(rules);
215		const evidence: ResolutionEvidence[] = [];
216		const normalizedIdentities = [input.winner, ...input.losers]
217			.map((entity) => ({
218				id: entity.id,
219				values: rules.map((rule) => normalizedResolutionRuleKeys(entity, rule)),
220			}))
221			.sort((left, right) => left.id - right.id);
222		let allLosersHaveAutoMatch = rules.length > 0;
223		let conflictingAutoIdentity = false;
224	
225		for (const loser of input.losers) {
226			let loserHasAutoMatch = false;
227			for (const rule of rules) {
228				const winnerKeys = normalizedResolutionRuleKeys(input.winner, rule);
229				const loserKeys = normalizedResolutionRuleKeys(loser, rule);
230				if (winnerKeys.length === 0 || loserKeys.length === 0) continue;
231				const loserKeySet = new Set(loserKeys);
232				const matches = winnerKeys.filter((key) => loserKeySet.has(key));
233				if (rule.onMatch === "auto_merge" && matches.length === 0) {
234					conflictingAutoIdentity = true;
235				}
