259		// singular/plural aliases are coalesced: stripping a trailing "s" from
260		// arbitrary configured paths would mangle custom names like `status`.
261		const ruleFieldLabel = [
262			...new Set(
263				rules.flatMap((rule) =>
264					rule.fields.map((field) => RULE_FIELD_ALIASES[field] ?? field),
265				),
266			),
