/**
 * Canonical normalization for identity values written to entity_identities.
 *
 * Connectors call these before emitting identifiers on events. The ingestion
 * pipeline also re-runs normalization as a defensive pass, so mismatched
 * connector behavior can't poison cross-channel matching.
 *
 * Glossary — "namespace" in this file:
 *   The string `namespace` here means an *identity scope* — the type of an
 *   external identifier (`email`, `phone`, `email_domain`, etc.). Only GENERIC
 *   namespaces are normalized here; connector-specific ones (slack_user_id,
 *   github_login, …) are normalized by their own connector module.
 *   It backs the `entity_identities.namespace` column and is the unit of
 *   uniqueness for cross-connector identity matching.
 *
 *   It is NOT the memory-scope axis. Per-agent memory scoping lives on
 *   `events.metadata.agent_id` (filtered via `search_memory`'s `agent_id`
 *   arg, populated by Lobu runtime capture). Identity
 *   namespaces and memory scopes are unrelated subsystems that happen to
 *   share an English word — don't conflate them when reading this file.
 */

import {
  getIdentityNamespaceDefinition,
  type IdentityNormalizerKind,
} from './identity-namespaces.js';

const PHONE_MIN_DIGITS = 7;
const PHONE_MAX_DIGITS = 15;

/**
 * Return the E.164-style digit string for a phone number, or null when the
 * input doesn't look like a phone. Strips all non-digit characters (including
 * the leading `+`); does not attempt country-code inference.
 *
 * Connectors should pass in values that already represent a specific E.164
 * number. The normalizer's job is cleanup (spaces, dashes, parens, `+`),
 * not country-code guessing.
 */
export function normalizePhone(raw: string | null | undefined): string | null {
  if (typeof raw !== 'string') return null;
  const digits = raw.replace(/\D+/g, '');
  if (digits.length < PHONE_MIN_DIGITS || digits.length > PHONE_MAX_DIGITS) return null;
  return digits;
}

export function normalizeEmail(raw: string | null | undefined): string | null {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim().toLowerCase();
  if (!trimmed) return null;
  const atIndex = trimmed.indexOf('@');
  if (atIndex <= 0 || atIndex === trimmed.length - 1) return null;
  if (trimmed.indexOf('@', atIndex + 1) !== -1) return null;
  const local = trimmed.slice(0, atIndex);
  const domain = trimmed.slice(atIndex + 1);
  if (!local || !domain) return null;
  if (domain.indexOf('.') === -1) return null;
  if (/\s/.test(trimmed)) return null;
  return trimmed;
}

/**
 * Extract the canonical domain from an email address. Runs the full email
 * validator first (so a malformed address yields null, never a bogus domain),
 * then returns the lowercased part after `@`. This is what backs the derived
 * `email_domain` identity namespace: `alice@Anthropic.com` → `anthropic.com`.
 *
 * Accepts either a full email or a bare domain — passing an already-extracted
 * `anthropic.com` returns it normalized, so the engine can re-run this
 * defensively over a value that may already be a domain.
 */
export function normalizeEmailDomain(raw: string | null | undefined): string | null {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim().toLowerCase();
  if (!trimmed || /\s/.test(trimmed)) return null;
  const atIndex = trimmed.indexOf('@');
  if (atIndex === -1) {
    // Bare domain: must contain a dot and no other @-like junk.
    if (trimmed.indexOf('.') === -1) return null;
    return trimmed;
  }
  const email = normalizeEmail(trimmed);
  if (!email) return null;
  return email.slice(email.indexOf('@') + 1);
}

/**
 * Normalize `auth_user_id` (Better Auth user id). Trim + lowercase so the
 * same user id from different clients collapses consistently.
 */
export function normalizeAuthUserId(raw: string | null | undefined): string | null {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim();
  if (!trimmed) return null;
  return trimmed;
}

function normalizeTrim(raw: string | null | undefined): string | null {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim();
  return trimmed ? trimmed : null;
}

/**
 * Apply a normalizer by its registry dispatch kind. The kind → function map
 * lives here; the namespace → kind map lives in the GENERIC identity namespace
 * registry (identity-namespaces.ts), so `normalizeIdentifier` has one source of
 * truth. Connector-specific namespaces are normalized by their own connector
 * module (server chains those before falling back here) and never reach this
 * switch.
 */
function applyNormalizer(
  kind: IdentityNormalizerKind,
  raw: string | null | undefined
): string | null {
  switch (kind) {
    case 'phone':
      return normalizePhone(raw);
    case 'email':
      return normalizeEmail(raw);
    case 'email_domain':
      return normalizeEmailDomain(raw);
    case 'auth_user_id':
      return normalizeAuthUserId(raw);
    case 'trim':
      return normalizeTrim(raw);
  }
}

/**
 * Normalize an identity value for a given GENERIC namespace. Dispatches through
 * the identity namespace registry's `normalizer` field. An unregistered
 * namespace falls back to trim-only so connector-owned namespaces still get
 * basic hygiene when they reach the generic fallback.
 */
export function normalizeIdentifier(
  namespace: string,
  raw: string | null | undefined
): string | null {
  const def = getIdentityNamespaceDefinition(namespace);
  if (!def) return normalizeTrim(raw);
  return applyNormalizer(def.normalizer, raw);
}

import { createHash } from "node:crypto";

type ResolutionDecision = "auto_merge" | "review";

export interface ResolutionEvidence {
	kind: string;
	identifier: string;
}

export interface ResolutionIdentity {
	namespace: string;
	identifier: string;
}

interface ResolutionEntity {
	id: number;
	metadata: Record<string, unknown>;
	/** Live identity claims that may not also exist in entity metadata. */
	identities?: ResolutionIdentity[];
}

/**
 * One entity's normalized rule keys, labelled by the rule that produced them —
 * the same label `evidence.kind` uses. These are the exact values the
 * fingerprint hashes, exposed so a proposal can record WHY it was proposed
 * rather than only who was involved. Rules that match nothing are omitted.
 */
export interface ResolutionKeySet {
	id: number;
	keys: Record<string, string[]>;
}

interface EntityResolutionAssessment {
	decision: ResolutionDecision;
	evidence: ResolutionEvidence[];
	policyHash: string;
	fingerprint: string;
	reason: string;
	resolutionKeys: ResolutionKeySet[];
}

interface ResolutionRule {
	fields: string[];
	normalizer: "email" | "phone" | "exact";
	onMatch: ResolutionDecision;
}

/**
 * Plural rule fields that name the same thing as their singular form, so the
 * human-facing reason says "email or phone" rather than listing all four.
 * Deliberately an explicit map: any field not listed here is printed verbatim.
 */
const RULE_FIELD_ALIASES: Record<string, string> = {
	emails: "email",
	phones: "phone",
};

const DEFAULT_PERSON_RESOLUTION_RULES: ResolutionRule[] = [
	{ fields: ["email"], normalizer: "email", onMatch: "review" },
	{ fields: ["emails"], normalizer: "email", onMatch: "review" },
	{ fields: ["phone"], normalizer: "phone", onMatch: "review" },
	{ fields: ["phones"], normalizer: "phone", onMatch: "review" },
];

function canonicalJson(value: unknown): string {
	if (Array.isArray(value)) {
		return `[${value.map(canonicalJson).join(",")}]`;
	}
	if (value && typeof value === "object") {
		const entries = Object.entries(value as Record<string, unknown>).sort(
			([left], [right]) => left.localeCompare(right),
		);
		return `{${entries
			.map(([key, item]) => `${JSON.stringify(key)}:${canonicalJson(item)}`)
			.join(",")}}`;
	}
	return JSON.stringify(value) ?? String(value);
}

function digest(value: unknown): string {
	return createHash("sha256").update(canonicalJson(value)).digest("hex");
}

function readPath(metadata: Record<string, unknown>, path: string): unknown {
	let current: unknown = metadata;
	for (const segment of path.split(".")) {
		if (!current || typeof current !== "object" || Array.isArray(current)) {
			return undefined;
		}
		current = (current as Record<string, unknown>)[segment];
	}
	return current;
}

function normalizeScalar(
	value: unknown,
	normalizer: ResolutionRule["normalizer"],
): string | null {
	if (typeof value !== "string" && typeof value !== "number") return null;
	const text = String(value).trim();
	if (!text) return null;
	if (normalizer === "phone") {
		if (!/^[+()0-9 .-]+$/.test(text)) return null;
		const digits = text.replace(/\D/g, "");
		return digits.length >= 7 && digits.length <= 15 ? digits : null;
	}
	if (normalizer === "email") {
		const email = text.toLocaleLowerCase("en-US");
		if (email.length > 512) return null;
		return /^[a-z0-9_%+-]+(?:\.[a-z0-9_%+-]+)*@[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$/.test(
			email,
		)
			? email
			: null;
	}
	return text;
}

function normalizeValues(
	value: unknown,
	normalizer: ResolutionRule["normalizer"],
): string[] {
	const values = Array.isArray(value) ? value : [value];
	return [
		...new Set(
			values
				.map((item) => normalizeScalar(item, normalizer))
				.filter((item): item is string => item !== null),
		),
	].sort();
}

export function readEntityResolutionRules(
	schema: unknown,
	options?: { entityTypeSlug?: string | null },
): ResolutionRule[] {
	if (!schema || typeof schema !== "object" || Array.isArray(schema)) {
		return options?.entityTypeSlug === "person"
			? DEFAULT_PERSON_RESOLUTION_RULES
			: [];
	}
	const config = (schema as Record<string, unknown>)["x-lobu-resolution"];
	if (config === undefined) {
		return options?.entityTypeSlug === "person"
			? DEFAULT_PERSON_RESOLUTION_RULES
			: [];
	}
	if (!config || typeof config !== "object" || Array.isArray(config)) return [];
	const rules = (config as Record<string, unknown>).rules;
	if (!Array.isArray(rules)) return [];
	return rules.flatMap((candidate) => {
		if (
			!candidate ||
			typeof candidate !== "object" ||
			Array.isArray(candidate)
		) {
			return [];
		}
		const record = candidate as Record<string, unknown>;
		const fields = Array.isArray(record.fields)
			? [
					...new Set(
						record.fields.flatMap((field) =>
							typeof field === "string" && field.trim().length > 0
								? [field.trim()]
								: [],
						),
					),
				]
			: [];
		const normalizer = record.normalizer;
		const onMatch = record.onMatch;
		if (
			fields.length === 0 ||
			(normalizer !== "email" &&
				normalizer !== "phone" &&
				normalizer !== "exact") ||
			(onMatch !== "auto_merge" && onMatch !== "review")
		) {
			return [];
		}
		return [{ fields, normalizer, onMatch }];
	});
}

export function normalizedResolutionRuleKeys(
	entity: ResolutionEntity,
	rule: ResolutionRule,
): string[] {
	let combinations: string[][] = [[]];
	for (const field of rule.fields) {
		// Identity-backed connector data follows the same field policy and
		// normalization as metadata when its namespace names that field.
		const raw = readPath(entity.metadata, field);
		const fromMetadata = Array.isArray(raw) ? raw : [raw];
		const fromIdentities = (entity.identities ?? [])
			.filter((identity) => identity.namespace === field)
			.map((identity) => identity.identifier);
		const values = normalizeValues(
			[...fromMetadata, ...fromIdentities],
			rule.normalizer,
		);
		if (values.length === 0) return [];
		combinations = combinations.flatMap((prefix) =>
			values.map((value) => [...prefix, value]),
		);
		if (combinations.length > 256) return [];
	}
	return combinations.map((parts) => parts.join("\u001f")).sort();
}

/**
 * Decide whether a duplicate proposal is deterministic under its entity type's
 * schema. The caller-provided evidence is deliberately ignored: every value is
 * recomputed from the locked workspace entities and the versioned type policy.
 */
export function assessEntityResolution(input: {
	metadataSchema: unknown;
	entityTypeSlug?: string | null;
	winner: ResolutionEntity;
	losers: ResolutionEntity[];
}): EntityResolutionAssessment {
	const rules = readEntityResolutionRules(input.metadataSchema, {
		entityTypeSlug: input.entityTypeSlug,
	});
	const policyHash = digest(rules);
	const evidence: ResolutionEvidence[] = [];
	const normalizedIdentities = [input.winner, ...input.losers]
		.map((entity) => ({
			id: entity.id,
			values: rules.map((rule) => normalizedResolutionRuleKeys(entity, rule)),
		}))
		.sort((left, right) => left.id - right.id);
	let allLosersHaveAutoMatch = rules.length > 0;
	let conflictingAutoIdentity = false;

	for (const loser of input.losers) {
		let loserHasAutoMatch = false;
		for (const rule of rules) {
			const winnerKeys = normalizedResolutionRuleKeys(input.winner, rule);
			const loserKeys = normalizedResolutionRuleKeys(loser, rule);
			if (winnerKeys.length === 0 || loserKeys.length === 0) continue;
			const loserKeySet = new Set(loserKeys);
			const matches = winnerKeys.filter((key) => loserKeySet.has(key));
			if (rule.onMatch === "auto_merge" && matches.length === 0) {
				conflictingAutoIdentity = true;
			}
			if (matches.length === 0) continue;
			for (const match of matches) {
				evidence.push({
					kind: rule.fields.join(" + "),
					identifier: match.split("\u001f").join(" · "),
				});
			}
			if (rule.onMatch === "auto_merge") loserHasAutoMatch = true;
		}
		allLosersHaveAutoMatch &&= loserHasAutoMatch;
	}

	const deduplicatedEvidence = [
		...new Map(
			evidence.map((item) => [`${item.kind}\u0000${item.identifier}`, item]),
		).values(),
	];
	const evidenceKinds = [
		...new Set(deduplicatedEvidence.map((item) => item.kind)),
	];
	// Name the fields this entity type actually resolves on ("email or phone"
	// for person) rather than assuming — another type may key on something else,
	// and a type with no rules at all resolves on nothing. Only the known
	// singular/plural aliases are coalesced: stripping a trailing "s" from
	// arbitrary configured paths would mangle custom names like `status`.
	const ruleFieldLabel = [
		...new Set(
			rules.flatMap((rule) =>
				rule.fields.map((field) => RULE_FIELD_ALIASES[field] ?? field),
			),
		),
	].join(" or ");
	const decision =
		allLosersHaveAutoMatch && !conflictingAutoIdentity
			? "auto_merge"
			: "review";
	const fingerprint = digest({
		policyHash,
		winnerId: input.winner.id,
		loserIds: input.losers.map((entity) => entity.id).sort((a, b) => a - b),
		normalizedIdentities,
	});
	// Derived from `normalizedIdentities` itself, not recomputed, so the recorded
	// keys cannot drift from what the fingerprint hashed. Labelling is the only
	// added step — the fingerprint input above is untouched, so exposing these
	// does not change any fingerprint and cannot strand pending proposals.
	const resolutionKeys: ResolutionKeySet[] = normalizedIdentities.map(
		({ id, values }) => {
			const keys: Record<string, string[]> = {};
			values.forEach((ruleKeys, index) => {
				const rule = rules[index];
				if (!rule || ruleKeys.length === 0) return;
				const label = rule.fields.join(" + ");
				keys[label] = [
					...new Set([...(keys[label] ?? []), ...ruleKeys]),
				].sort();
			});
			return { id, keys };
		},
	);

	return {
		decision,
		evidence: deduplicatedEvidence,
		policyHash,
		fingerprint,
		resolutionKeys,
		// Addressed to the human deciding the approval, so each branch says what
		// the workspace could verify and what it now needs from them — not what
		// the rules engine did internally.
		reason:
			decision === "auto_merge"
				? "The entity type declares this normalized identity unique."
				: conflictingAutoIdentity
					? "These records carry conflicting identities that are configured as unique, so merging them needs your judgement."
					: deduplicatedEvidence.length > 0
						? `Matching ${evidenceKinds.join(" and ")} points to the same thing, but that is not enough to merge automatically under this entity type's policy, so it needs your judgement.`
						: ruleFieldLabel
							? `No matching ${ruleFieldLabel} could be verified automatically, so this merge needs your judgement.`
							: "This entity type has no automatic matching rules, so every merge needs your judgement.",
	};
}

