1	import { type DbClient, pgBigintArray } from "../db/client";
2	import { loadLiveEntityIdentities } from "./identities";
3	import {
4		assessEntityResolution,
5		type EntityResolutionAssessment,
6		RESOLUTION_FINGERPRINT_VERSION,
7	} from "./policy";
8	
9	/**
10	 * Why a reviewed merge could not be applied against its stored fingerprint.
11	 *
12	 * `changed` means the workspace moved under the reviewer: same hash inputs,
13	 * different values. The proposal is genuinely stale.
14	 *
15	 * `incomparable` means the stored digest has no known current version, so it
16	 * cannot be compared at all. Nothing about the entities necessarily changed —
17	 * treating this as staleness makes the proposal permanently unapprovable,
18	 * because every retry recomputes the same mismatch.
19	 */
20	export type ResolutionFingerprintFailure = "changed" | "incomparable";
21	
22	export class ResolutionFingerprintError extends Error {
23		readonly failure: ResolutionFingerprintFailure;
24		/** The freshly computed assessment, so a caller can refresh without redoing the work. */
25		readonly assessment: EntityResolutionAssessment;
26	
27		constructor(
28			failure: ResolutionFingerprintFailure,
29			assessment: EntityResolutionAssessment,
30		) {
31			super(
32				failure === "incomparable"
33					? "Merge evidence was recorded under an older resolution format and has been re-checked"
34					: "Merge evidence or resolution policy changed after review was requested",
35			);
36			this.name = "ResolutionFingerprintError";
37			this.failure = failure;
38			this.assessment = assessment;
39		}
40	}
41	
42	/** Lock and re-evaluate a reviewed merge immediately before applying it. */
43	export async function assertResolutionFingerprintCurrent(
44		db: DbClient,
45		input: {
46			organizationId: string;
47			winnerId: number;
48			loserIds: number[];
49			expectedFingerprint: string;
50			/**
51			 * Which format produced `expectedFingerprint`. Required, and deliberately
52			 * without a default: a live fingerprint computed in this process is current
53			 * by construction, while an unstamped stored proposal has unknown provenance.
54			 * Guessing a version could silently accept incomparable evidence.
55			 */
56			expectedVersion: number | null;
57		},
58	): Promise<void> {
59		const ids = [...input.loserIds, input.winnerId].sort((a, b) => a - b);
60		const rows = await db<{
61			id: number;
62			entity_type_id: number;
63			metadata: Record<string, unknown>;
64			metadata_schema: Record<string, unknown> | null;
65			entity_type_slug: string;
66		}>`
67			SELECT entity.id, entity.entity_type_id, entity.metadata,
68			       type.metadata_schema, type.slug AS entity_type_slug
69			FROM entities entity
70			JOIN entity_types type ON type.id = entity.entity_type_id
71			WHERE entity.organization_id = ${input.organizationId}
72			  AND entity.id = ANY(${pgBigintArray(ids)}::bigint[])
73			  AND entity.deleted_at IS NULL
74			ORDER BY entity.id
75			FOR UPDATE OF entity
76			FOR SHARE OF type
77		`;
78		if (rows.length !== ids.length) {
79			throw new Error(
80				"Merge evidence is stale because an entity is no longer live",
81			);
82		}
83		if (new Set(rows.map((row) => Number(row.entity_type_id))).size !== 1) {
84			throw new Error("Merge evidence is stale because entity types changed");
85		}
86		const byId = new Map(rows.map((row) => [Number(row.id), row]));
87		const winner = byId.get(input.winnerId);
88		if (!winner)
89			throw new Error("Merge evidence is stale because the winner changed");
90		const identities = await loadLiveEntityIdentities(db, {
91			organizationId: input.organizationId,
92			entityIds: ids,
93			forUpdate: true,
94		});
95		const assessment = assessEntityResolution({
96			metadataSchema: winner.metadata_schema,
97			entityTypeSlug: winner.entity_type_slug,
98			winner: {
99				id: input.winnerId,
100				metadata: winner.metadata ?? {},
101				identities: identities.get(input.winnerId) ?? [],
102			},
103			losers: input.loserIds.map((loserId) => ({
104				id: loserId,
105				metadata: byId.get(loserId)?.metadata ?? {},
106				identities: identities.get(loserId) ?? [],
107			})),
108		});
109		// Version first: a digest from an older input set carries no information
110		// about drift, so comparing it would report a change that may not exist.
111		if (input.expectedVersion !== RESOLUTION_FINGERPRINT_VERSION) {
112			throw new ResolutionFingerprintError("incomparable", assessment);
113		}
114		if (assessment.fingerprint !== input.expectedFingerprint) {
115			throw new ResolutionFingerprintError("changed", assessment);
116		}
117	}

