import { describe, expect, it } from "vitest";
import {
	droppedEvidence,
	gainedEvidence,
	isEvidenceAtLeastAsStrong,
} from "./evidence-strength";

const phone = { kind: "phone", identifier: "905395102240" };
const email = { kind: "email", identifier: "a@example.com" };

describe("isEvidenceAtLeastAsStrong", () => {
	it("treats identical evidence as still holding", () => {
		expect(isEvidenceAtLeastAsStrong([phone], [phone])).toBe(true);
	});

	it("applies a merge whose evidence was empty at review time", () => {
		// The 18 stranded prod proposals: reviewed with no machine evidence, so the
		// decision rested on human judgement that recomputation cannot revoke.
		expect(isEvidenceAtLeastAsStrong([], [phone])).toBe(true);
		expect(isEvidenceAtLeastAsStrong([], [])).toBe(true);
	});

	it("applies when the re-check proves strictly more", () => {
		expect(isEvidenceAtLeastAsStrong([phone], [phone, email])).toBe(true);
	});

	it("refuses when an item the reviewer relied on is gone", () => {
		expect(isEvidenceAtLeastAsStrong([phone], [])).toBe(false);
		expect(isEvidenceAtLeastAsStrong([phone, email], [email])).toBe(false);
	});

	it("refuses when the identifier changed under the same kind", () => {
		// Same kind is not the same proof — a different phone is a different fact.
		expect(
			isEvidenceAtLeastAsStrong([phone], [{ kind: "phone", identifier: "1" }]),
		).toBe(false);
	});

	it("does not let kind and identifier bleed across the separator", () => {
		// Plain concatenation would make these two equal and silently accept a
		// merge on evidence that was never proven.
		const reviewed = [{ kind: "a�b", identifier: "c" }];
		const current = [{ kind: "a", identifier: "b�c" }];
		expect(isEvidenceAtLeastAsStrong(reviewed, current)).toBe(false);
	});

	it("ignores ordering and duplication", () => {
		expect(
			isEvidenceAtLeastAsStrong([phone, email], [email, phone, phone]),
		).toBe(true);
	});
});

describe("droppedEvidence / gainedEvidence", () => {
	it("names what stopped holding, for the reviewer-facing message", () => {
		expect(droppedEvidence([phone, email], [email])).toEqual([phone]);
		expect(droppedEvidence([phone], [phone])).toEqual([]);
	});

	it("names what the re-check newly proved", () => {
		expect(gainedEvidence([], [phone])).toEqual([phone]);
		expect(gainedEvidence([phone], [phone])).toEqual([]);
	});
});

