		SELECT evidence FROM entity_merges
		WHERE organization_id = ${org.id} AND loser_entity_id = ${loser.id}
	`;
	expect(ledger.evidence).toEqual([
		expect.objectContaining({ kind: "phone", identifier: "905395102240" }),
	]);
