it("applies an unverifiable merge in one approval when re-assessment proves more", async () => {
	// The prod shape of the 18 stranded proposals: an unstamped fingerprint,
	// evidence [] at review time, and a phone that both sides actually share.
	// Re-assessment gains that phone and drops nothing, so the reviewer's
	// approval already covers this merge and must not be asked for twice.
	const org = await createTestOrganization({ name: "Strengthened Merge Org" });
	const user = await createTestUser();
	await addUserToOrganization(user.id, org.id, "owner");
