1	import type { ResolutionEvidence, ResolutionKeySet } from "./policy";
2	
3	/** Preserve the boundary between two free-form values without a delimiter. */
4	const evidenceKey = (item: ResolutionEvidence): string =>
5		JSON.stringify([item.kind, item.identifier]);
6	
7	/**
8	 * A strict evidence gain preserves everything reviewed and adds at least one
9	 * new proof. Unchanged evidence is not enough because the fingerprint may have
10	 * moved on an unmatched identity that evidence does not expose.
11	 */
12	export function hasEvidenceStrengthened(
13		reviewed: ResolutionEvidence[],
14		current: ResolutionEvidence[],
15	): boolean {
16		return (
17			droppedEvidence(reviewed, current).length === 0 &&
18			gainedEvidence(reviewed, current).length > 0
19		);
20	}
21	
22	/** Evidence present at review time that the current assessment no longer proves. */
23	export function droppedEvidence(
24		reviewed: ResolutionEvidence[],
25		current: ResolutionEvidence[],
26	): ResolutionEvidence[] {
27		const currentKeys = new Set(current.map(evidenceKey));
28		return reviewed.filter((item) => !currentKeys.has(evidenceKey(item)));
29	}
30	
31	/** Evidence the current assessment proves that was not recorded at review time. */
32	export function gainedEvidence(
33		reviewed: ResolutionEvidence[],
34		current: ResolutionEvidence[],
35	): ResolutionEvidence[] {
36		const reviewedKeys = new Set(reviewed.map(evidenceKey));
37		return current.filter((item) => !reviewedKeys.has(evidenceKey(item)));
38	}
39	
40	/**
41	 * Whether a merge re-check added proof without changing any unmatched
42	 * resolution key. Evidence alone cannot establish that: a new shared phone can
43	 * hide a different new email on each side because only matches become evidence.
44	 */
45	export function hasMergeEvidenceStrengthened(input: {
