\t\t\t\t\t\t\torganizationId: org.id,
\t\t\t\t\t\t\twinnerId: winner.id,
\t\t\t\t\t\t\tloserIds: [loser.id],
\t\t\t\t\t\t});
\t\t\t\t\t}),
