	duplicates: Record<string, unknown>[];
	winner: Record<string, unknown>;
} {
	const loser = (args.current?.loser ?? {}) as Record<string, unknown>;
	const duplicates = Array.isArray(args.current?.duplicates)
		? (args.current.duplicates as Record<string, unknown>[])
		: [loser];
	return {
		duplicates,
		winner: (args.current?.winner ?? {}) as Record<string, unknown>,
	};
}

function matchExplanation(
	evidence: Record<string, unknown>[],
	recordCount: number,
): string {
	if (evidence.length === 0) {
		return "No deterministic identity match details are available for these records.";
	}
	if (evidence.length === 1 && recordCount === 2) {
		const [item] = evidence;
		return `Both records have the same ${String(item?.kind ?? "identity")}: ${String(item?.identifier ?? "")}.`;
	}
	return `Recorded match evidence:\n${evidence
		.map(
			(item) =>
				`• ${String(item.kind ?? "Identity")}: ${String(item.identifier ?? "")}`,
		)
		.join("\n")}`;
}

function entityBlock(
	label: "Duplicate" | "Canonical",
	entity: Record<string, unknown>,
	reviewUrls: Set<string>,
): InteractionBlock {
	const id = String(entity.id ?? label.toLowerCase());
	let recordLink: InteractionAction | undefined;
	const sourceLinks: InteractionAction[] = [];
	const sourceUrls = new Set<string>();
	if (typeof entity.href === "string") {
		reviewUrls.add(entity.href);
		recordLink = {
			id: `entity-${id}`,
			label: "Open record",
			variant: "ghost",
			icon: "external",
			terminal: false,
			tool: "open_review_link",
			args: { url: entity.href },
		};
	}
	const details = new Set<string>();
	for (const identity of Array.isArray(entity.identities)
		? (entity.identities as Record<string, unknown>[])
		: []) {
		const source = String(
			identity.connection_name ?? identity.source_connector ?? "Unknown source",
		);
		details.add(
			`${source} · ${String(identity.namespace ?? "identity")}: ${String(identity.identifier ?? "")}`,
		);
		if (
			typeof identity.connection_href !== "string" ||
			sourceUrls.has(identity.connection_href)
		) {
			continue;
		}
		sourceUrls.add(identity.connection_href);
		reviewUrls.add(identity.connection_href);
		sourceLinks.push({
			id: `connection-${String(identity.id ?? identity.connection_href)}`,
			label: `Open source: ${source}`,
			variant: "ghost",
			icon: "external",
			terminal: false,
			tool: "open_review_link",
			args: { url: identity.connection_href },
		});
	}
	return {
		type: "entity",
		id,
		label,
		name: String(entity.name ?? `Entity ${id}`),
		details: [...details],
		recordLink,
		sourceLinks,
	};
}

function evidenceRecords(value: unknown): Record<string, unknown>[] {
	return Array.isArray(value)
		? value.filter(
				(item): item is Record<string, unknown> =>
					Boolean(item) && typeof item === "object" && !Array.isArray(item),
			)
		: [];
}

function evidenceLine(item: Record<string, unknown>): string {
	return `${String(item.kind ?? "Identity")}: ${String(item.identifier ?? "")}`;
}

/**
 * Explain how a re-checked proposal differs from the one that was reviewed.
 *
 * The server records this on refresh because only it knows both sides: the card
 * itself only ever receives the current snapshot. Absent for a first-time
 * proposal, where there is nothing to compare against.
 */
function evidenceChangeBlock(
	value: unknown,
): { block: InteractionBlock; weakened: boolean } | null {
	if (!value || typeof value !== "object" || Array.isArray(value)) return null;
	const change = value as Record<string, unknown>;
	const dropped = evidenceRecords(change.dropped);
	const gained = evidenceRecords(change.gained);
	if (dropped.length === 0 && gained.length === 0) return null;

	const lines: string[] = [];
	// Losses first: they are the reason this is back in front of a human.
	for (const item of dropped) lines.push(`− No longer proven — ${evidenceLine(item)}`);
	for (const item of gained) lines.push(`+ Newly proven — ${evidenceLine(item)}`);
	return {
		weakened: dropped.length > 0,
		block: {
			type: "text",
			label:
				dropped.length > 0
					? "What changed since you reviewed this"
					: "What the re-check newly found",
			value: lines.join("\n"),
		},
	};
}

export function buildEntityMergeInteraction(
	args: EntityMergeInteractionArgs,
): EntityMergeInteractionResult {
	const { duplicates, winner } = recordsFrom(args);
	const evidence = evidenceRecords(args.proposal?.evidence);
	const reviewUrls = new Set<string>();
	const status = typeof args.status === "string" ? args.status : "pending";
	const pending = status === "pending";
	const statusLabel =
		status === "rejected"
			? "Kept separate"
			: status === "failed"
				? "Failed"
				: "Approved";
	const reason =
		typeof args.reason === "string"
			? args.reason
			: typeof args.proposal?.reason === "string"
				? args.proposal.reason
				: null;
	const blocks: InteractionBlock[] = [
		{
			type: "text",
			label: "Why Lobu thinks they match",
			value: matchExplanation(evidence, duplicates.length + 1),
		},
	];
	if (reason) {
		blocks.push({
			type: "text",
			label: "Why this needs review",
			value: reason,
			muted: true,
		});
	}
	// Sits directly under the reason, above the records: a reviewer who already
	// looked at this card once needs to see what moved before anything else.
	const change = evidenceChangeBlock(args.proposal?.evidence_change);
	if (change) blocks.push(change.block);
	blocks.push(
		...duplicates.map((entity) => entityBlock("Duplicate", entity, reviewUrls)),
		entityBlock("Canonical", winner, reviewUrls),
		{
			type: "text",
			value: pending
				? `If approved, ${duplicates.length === 1 ? "the" : "each"} duplicate's relationships and aliases will move to the canonical record.`
				: typeof args.reviewedByName === "string"
					? `${statusLabel} by ${args.reviewedByName}.`
					: `${statusLabel}.`,
			muted: true,
		},
	);

	const actions: InteractionAction[] = pending
		? [
				{
					id: "approve",
					label: "Approve merge",
					variant: "primary",
					icon: "check",
					tool: "manage_operations",
					args: { action: "approve" },
					resolvedLabel: "Merge approved and is being applied.",
				},
				{
					id: "reject",
					label: "Keep separate",
					variant: "outline",
					icon: "x",
					confirm: true,
					confirmPrompt: "Keep these entities separate?",
					tool: "manage_operations",
					args: { action: "reject" },
					resolvedLabel: "The entities were kept separate.",
				},
			]
		: [];

	return {
		view: {
			title: `Merge ${duplicates.length} duplicate ${duplicates.length === 1 ? "record" : "records"}${pending ? "" : ` · ${statusLabel}`}`,
			tone: pending || status === "failed" ? "warning" : "default",
			blocks,
			actions,
		},
		reviewUrls,
	};
}

export function buildAutomaticEntityMergeInteraction(
	args: AutomaticEntityMergeInteractionArgs,
): EntityMergeInteractionResult {
	const loser =
		args.loser && typeof args.loser === "object" && !Array.isArray(args.loser)
			? { ...(args.loser as Record<string, unknown>) }
			: {};
	const winner =
		args.winner &&
		typeof args.winner === "object" &&
		!Array.isArray(args.winner)
			? { ...(args.winner as Record<string, unknown>) }
			: {};
	if (typeof args.loserHref === "string") loser.href = args.loserHref;
	if (typeof args.winnerHref === "string") winner.href = args.winnerHref;

	const evidence = evidenceRecords(args.evidence);
	const reviewUrls = new Set<string>();
	const active = args.status === "active";
	const canUndo = active && args.canUndo === true;
	const actions: InteractionAction[] = canUndo
		? [
				{
					id: "undo",
					label: "Undo merge",
					variant: "outline",
					icon: "x",
					confirm: true,
					confirmPrompt: "Undo this automatic merge?",
					tool: "manage_entity",
					args: { action: "unmerge" },
					resolvedLabel: "Merge undone.",
				},
			]
		: [];

	return {
		view: {
			title: active ? "Merged automatically" : "Automatic merge undone",
			tone: active ? "default" : "warning",
			blocks: [
				{
					type: "text",
					label: "Why Lobu merged them",
					value: matchExplanation(evidence, 2),
				},
				entityBlock("Duplicate", loser, reviewUrls),
				entityBlock("Canonical", winner, reviewUrls),
				{
					type: "text",
					value: active
						? "The entity type's deterministic identity rule applied this merge without human review."
						: "This automatic merge was undone.",
					muted: true,
				},
			],
			actions,
		},
		reviewUrls,
	};
}

