/**
 * Seed the four merge-approval card states so they can be clicked in the UI.
 * Throwaway: delete after the manual check.
 */
import { getDb } from "../db/client";
import type { Env } from "../index";
import { manageEntity } from "../tools/admin/manage_entity";
import { manageOperations } from "../tools/admin/manage_operations";
import type { ToolContext } from "../tools/registry";
import { initWorkspaceProvider } from "../workspace";

const ORG = process.env.SEED_ORG as string;
const USER = process.env.SEED_USER as string;
const env = {} as Env;

const humanCtx = {
	organizationId: ORG,
	userId: USER,
	memberRole: "owner",
	scopes: ["mcp:read", "mcp:write", "mcp:admin"],
} as ToolContext;

const agentCtx = {
	...humanCtx,
	userId: null,
	agentId: "personal-agent",
} as ToolContext;

async function ensurePersonType(db: ReturnType<typeof getDb>) {
	const [existing] = await db<{ id: number }>`
		SELECT id FROM entity_types WHERE organization_id = ${ORG} AND slug = 'person'
	`;
	if (existing) return Number(existing.id);
	const [created] = await db<{ id: number }>`
		INSERT INTO entity_types (slug, name, organization_id, created_by, metadata_schema)
		VALUES ('person', 'Person', ${ORG}, ${USER}, ${db.json({
			type: "object",
			properties: { phone: { type: "string" }, email: { type: "string" } },
		})})
		RETURNING id
	`;
	return Number(created.id);
}

async function person(
	db: ReturnType<typeof getDb>,
	typeId: number,
	name: string,
	slug: string,
) {
	const [row] = await db<{ id: number }>`
		INSERT INTO entities (organization_id, entity_type_id, name, slug, created_by)
		VALUES (${ORG}, ${typeId}, ${name}, ${slug}, ${USER})
		RETURNING id
	`;
	return Number(row.id);
}

async function identity(
	db: ReturnType<typeof getDb>,
	entityId: number,
	namespace: string,
	identifier: string,
) {
	await db`
		INSERT INTO entity_identities (organization_id, entity_id, namespace, identifier)
		VALUES (${ORG}, ${entityId}, ${namespace}, ${identifier})
	`;
}

async function propose(loserId: number, winnerId: number) {
	const res = (await manageEntity(
		{ action: "merge", entity_id: loserId, winner_entity_id: winnerId },
		env,
		agentCtx,
	)) as unknown as { approval_queued?: boolean; approval_run_id?: number };
	if (!res.approval_run_id) {
		throw new Error(`expected an approval, got ${JSON.stringify(res)}`);
	}
	return res.approval_run_id;
}

async function main() {
	await initWorkspaceProvider();
	const db = getDb();
	const typeId = await ensurePersonType(db);
	const stamp = Date.now();
	const out: string[] = [];

	// A — WEAKENED: shared phone at review time, gone by the time it is approved.
	{
		const w = await person(db, typeId, "Ayşe Demir", `ayse-demir-${stamp}`);
		const l = await person(db, typeId, "Ayse D.", `ayse-d-${stamp}`);
		await identity(db, w, "phone", "+90 535 595 1101");
		await identity(db, l, "phone", "905355951101");
		const runId = await propose(l, w);
		await db`UPDATE entity_identities SET deleted_at = now()
			WHERE organization_id = ${ORG} AND entity_id = ${l}`;
		const first = await manageOperations(
			{ action: "approve", run_id: runId },
			env,
			humanCtx,
		);
		out.push(
			`A weakened      run=${runId} first-approve => ${JSON.stringify(first).slice(0, 90)}`,
		);
	}

	// B — UNCHANGED evidence: an identity appears on ONE side after review, so the
	// fingerprint moves while the evidence set stands still.
	{
		const w = await person(db, typeId, "Mehmet Kaya", `mehmet-kaya-${stamp}`);
		const l = await person(db, typeId, "M. Kaya", `m-kaya-${stamp}`);
		const runId = await propose(l, w);
		await identity(db, l, "phone", "905321234567");
		const first = await manageOperations(
			{ action: "approve", run_id: runId },
			env,
			humanCtx,
		);
		out.push(
			`B unchanged     run=${runId} first-approve => ${JSON.stringify(first).slice(0, 90)}`,
		);
	}

	// C — STRENGTHENED, the prod shape of the 18: unstamped digest, empty recorded
	// evidence, and a phone both sides really share. Must apply on ONE click.
	{
		const w = await person(db, typeId, "Fatma Şahin", `fatma-sahin-${stamp}`);
		const l = await person(db, typeId, "Fatma S.", `fatma-s-${stamp}`);
		await identity(db, w, "phone", "+90 533 111 2233");
		await identity(db, l, "phone", "905331112233");
		const runId = await propose(l, w);
		const [minted] = await db<{ action_input: Record<string, unknown> }>`
			SELECT action_input FROM runs WHERE id = ${runId}
		`;
		const stale = {
			...minted.action_input,
			resolution_fingerprint: "0".repeat(64),
			evidence: [],
		};
		delete stale.resolution_fingerprint_version;
		await db`UPDATE runs SET action_input = ${db.json(stale)} WHERE id = ${runId}`;
		out.push(`C strengthened  run=${runId} (untouched — click ONCE to apply)`);
	}

	// D — control: an ordinary first-time proposal, no re-check.
	{
		const w = await person(db, typeId, "Zeynep Yıldız", `zeynep-yildiz-${stamp}`);
		const l = await person(db, typeId, "Z. Yildiz", `z-yildiz-${stamp}`);
		await identity(db, w, "email", "zeynep@example.com");
		await identity(db, l, "phone", "905339998877");
		const runId = await propose(l, w);
		out.push(`D first-time     run=${runId} (untouched — no change block)`);
	}

	for (const line of out) console.log(line);

	const rows = await db<{
		id: number;
		evidence_change: unknown;
		error_message: string | null;
	}>`
		SELECT id, action_input->'evidence_change' AS evidence_change, error_message
		FROM runs WHERE action_key = 'entity_change' AND organization_id = ${ORG}
		ORDER BY id
	`;
	console.log("\nrun states:");
	for (const row of rows) {
		console.log(
			`  ${row.id}  change=${JSON.stringify(row.evidence_change)}  msg=${(row.error_message ?? "-").slice(0, 70)}`,
		);
	}
}

main().then(
	() => process.exit(0),
	(error) => {
		console.error(error);
		process.exit(1);
	},
);

