/**
 * THROWAWAY — reproduces the exact shape of the 16 merge approvals still pending
 * in prod org `buremba`, to prove how many clicks each needs after #2330/#2337.
 *
 * Prod shape: winner is a `run_sdk`-imported person carrying a raw
 * `metadata.phone`; loser is a WhatsApp entity carrying a clean
 * `entity_identities` row with namespace 'phone'. The proposal was minted
 * 2026-07-22, BEFORE #2152 taught the matcher to read metadata and BEFORE #2321
 * recorded resolution_keys — so the stored snapshot has `evidence: []`, no
 * `resolution_keys`, an absent `resolution_fingerprint_version`, and a
 * fingerprint that can never revalidate.
 */

import { beforeEach, describe, expect, it } from "vitest";
import type { Env } from "../../../index";
import { manageEntity } from "../../../tools/admin/manage_entity";
import { manageOperations } from "../../../tools/admin/manage_operations";
import type { ToolContext } from "../../../tools/registry";
import { initWorkspaceProvider } from "../../../workspace";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import {
	addUserToOrganization,
	createTestEntity,
	createTestOrganization,
	createTestUser,
} from "../../setup/test-fixtures";

const env = {} as Env;

function ctx(orgId: string, userId: string): ToolContext {
	return {
		organizationId: orgId,
		userId,
		memberRole: "owner",
		scopes: ["mcp:read", "mcp:write", "mcp:admin"],
	} as ToolContext;
}

describe("prod-shape merge approvals (buremba's pending 16)", () => {
	beforeEach(async () => {
		await cleanupTestDatabase();
		await initWorkspaceProvider();
	});

	/**
	 * @param winnerMetadataPhone raw string as the importer wrote it
	 * @param loserIdentityPhone  normalized identity claim from WhatsApp
	 */
	async function stalePendingMerge(
		winnerMetadataPhone: string,
		loserIdentityPhone: string,
	) {
		const org = await createTestOrganization({ name: "Prod Shape Org" });
		const user = await createTestUser();
		await addUserToOrganization(user.id, org.id, "owner");
		const sql = getTestDb();

		const winner = await createTestEntity({
			name: "Imported Contact",
			entity_type: "person",
			organization_id: org.id,
			created_by: user.id,
		});
		const loser = await createTestEntity({
			name: `${loserIdentityPhone}@s.whatsapp.net`,
			entity_type: "person",
			organization_id: org.id,
			created_by: user.id,
		});

		// Winner: raw metadata phone, no identity claim (the run_sdk import path).
		await sql`
			UPDATE entities SET metadata = ${sql.json({ phone: winnerMetadataPhone })}
			WHERE id = ${winner.id}
		`;
		// Loser: real identity claims, exactly as the WhatsApp connector writes them.
		await sql`
			INSERT INTO entity_identities (organization_id, entity_id, namespace, identifier)
			VALUES
				(${org.id}, ${loser.id}, 'phone', ${loserIdentityPhone}),
				(${org.id}, ${loser.id}, 'wa_jid', ${`${loserIdentityPhone}@s.whatsapp.net`})
		`;

		const queued = (await manageEntity(
			{ action: "merge", entity_id: loser.id, winner_entity_id: winner.id },
			env,
			{
				...ctx(org.id, user.id),
				userId: null,
				agentId: "personal-agent",
			} as ToolContext,
		)) as unknown as { approval_run_id: number };

		// Rewind the snapshot to its pre-#2152 / pre-#2321 state: no evidence, no
		// recorded keys, no version stamp, and a fingerprint that cannot revalidate.
		await sql`
			UPDATE runs SET action_input =
				(action_input - 'resolution_fingerprint_version')
				|| jsonb_build_object(
					'evidence', '[]'::jsonb,
					'resolution_fingerprint', repeat('0', 64)
				)
			WHERE id = ${queued.approval_run_id}
		`;

		return { org, user, winner, loser, runId: queued.approval_run_id, sql };
	}

	async function mergedState(
		sql: ReturnType<typeof getTestDb>,
		winnerId: number,
		loserId: number,
	) {
		const [w] = await sql`
			SELECT deleted_at, merged_into FROM entities WHERE id = ${winnerId}
		`;
		const [l] = await sql`
			SELECT deleted_at, merged_into FROM entities WHERE id = ${loserId}
		`;
		return {
			winnerAlive: w.deleted_at === null && w.merged_into === null,
			loserMergedIntoWinner:
				l.deleted_at !== null && Number(l.merged_into) === winnerId,
		};
	}

	it("applies in ONE click when both sides spell the phone identically (12 of 16)", async () => {
		// Run 702089's shape: metadata '+905322356586' vs identity '905322356586'.
		const { org, user, winner, loser, runId, sql } = await stalePendingMerge(
			"+905322356586",
			"905322356586",
		);

		const result = await manageOperations(
			{ action: "approve", run_id: runId },
			env,
			ctx(org.id, user.id),
		);

		expect("error" in result ? result.error : null).toBeNull();
		expect(await mergedState(sql, winner.id, loser.id)).toEqual({
			winnerAlive: true,
			loserMergedIntoWinner: true,
		});
	});

	it("needs TWO clicks when the winner's phone is national format (4 of 16)", async () => {
		// Run 702091's shape: metadata '05324764881' vs identity '905324764881'.
		// normalizeScalar strips punctuation but never guesses a country code, so
		// these never match and the re-check finds NO evidence at all.
		const { org, user, winner, loser, runId, sql } = await stalePendingMerge(
			"05324764881",
			"905324764881",
		);

		const first = await manageOperations(
			{ action: "approve", run_id: runId },
			env,
			ctx(org.id, user.id),
		);
		// Re-presented, not applied — and the card must NOT claim evidence was lost,
		// because there never was any.
		expect("error" in first && first.error).toMatch(/re-checked/i);
		expect(await mergedState(sql, winner.id, loser.id)).toEqual({
			winnerAlive: true,
			loserMergedIntoWinner: false,
		});

		const [refreshed] = await sql`
			SELECT action_input FROM runs WHERE id = ${runId}
		`;
		const input = refreshed.action_input as Record<string, unknown>;
		expect(input.resolution_fingerprint_version).toBe(2);
		expect(input.evidence).toEqual([]);
		expect(input.evidence_change).toEqual({ dropped: [], gained: [] });

		// Second click: the fingerprint is current now, so it applies.
		const second = await manageOperations(
			{ action: "approve", run_id: runId },
			env,
			ctx(org.id, user.id),
		);
		expect("error" in second ? second.error : null).toBeNull();
		expect(await mergedState(sql, winner.id, loser.id)).toEqual({
			winnerAlive: true,
			loserMergedIntoWinner: true,
		});
	});
});

