	// Resolve identity claims BEFORE inserting. The connector path
	// (`entity-link-upsert`) has always looked up owners first and attached to
	// what exists; this path used to insert unconditionally, which is how an
	// import of contacts that a connector already knew produced duplicate
	// people for a human to merge away afterwards.
	const requestedIdentities = normalizeRequestedIdentities(args.identities);
	let attachedToExisting = false;
	let contestedIdentities: ResolutionIdentity[] = [];
	if (requestedIdentities.length > 0) {
		const sql = getDb();
		const owners = await findEntitiesByIdentity(sql, {
			organizationId: ctx.organizationId,
			identities: requestedIdentities,
		});
		const resolved = resolveIdentityOwner(owners, requestedIdentities);
		if (resolved.decision === "ambiguous") {
			throw new ToolUserError(
				`These identifiers already belong to different entities (${resolved.candidateEntityIds.join(", ")}), so creating one entity for them would silently fuse separate records. Merge the existing entities first with manage_entity(action='merge'), or create with only the identifiers of a single one.`,
				409,
			);
		}
		if (resolved.decision === "attach" && resolved.entityId !== undefined) {
			const existing = await getEntity(resolved.entityId, env, ctx);
			// A claim can name an entity the caller cannot read (another branch of
			// the org tree). Fall through to create rather than leak its existence.
			if (existing) {
				const { contested } = await attachEntityIdentities(sql, {
					organizationId: ctx.organizationId,
					entityId: existing.id,
					identities: requestedIdentities,
					sourceConnector: identityWriterTag(ctx),
				});
				return buildCreateResult(existing, {
					attachedToExisting: true,
					contested,
				});
			}
		}
	}

	const entity = await createEntity(entityData, {
		hookContext: {
			organizationId: ctx.organizationId,
			userId: ctx.userId,
			env,
		},
	});

	if (requestedIdentities.length > 0) {
		const { contested } = await attachEntityIdentities(getDb(), {
			organizationId: ctx.organizationId,
			entityId: entity.id,
			identities: requestedIdentities,
			sourceConnector: identityWriterTag(ctx),
		});
		contestedIdentities = contested;
	}

	return buildCreateResult(entity, {
		attachedToExisting,
		contested: contestedIdentities,
	});
}

/**
 * Drop claims whose value does not survive its namespace's normalizer — an
 * unparseable phone is a display string, not an identity, and storing it as one
 * would make it collide with nothing while looking authoritative.
 */
function normalizeRequestedIdentities(
	requested: Array<{ namespace: string; identifier: string }> | undefined,
): ResolutionIdentity[] {
	if (!requested || requested.length === 0) return [];
	const out = new Map<string, ResolutionIdentity>();
	for (const item of requested) {
		const namespace = item.namespace.trim();
		if (!namespace) continue;
		const identifier = normalizeIdentifier(namespace, item.identifier);
		if (!identifier) continue;
		out.set(JSON.stringify([namespace, identifier]), { namespace, identifier });
	}
	return [...out.values()];
}

