	// thing, so it is surfaced rather than dropped — but it is NOT stolen from
	// whoever holds it, and it is not grounds to refuse the write.
	const warnings = [...(entity.warnings ?? [])];
	if (identity.contested.length > 0) {
		warnings.push(
			`Kept with their existing entities, not attached here: ${identity.contested
				.map((i) => `${i.namespace} ${i.identifier}`)
				.join(", ")}. If these are the same thing, merge them with manage_entity(action='merge').`,
		);
	}

	return {
		action: "create",
		attached_to_existing: attachedToExisting,
		entity: {
			id: entityDetails.id,
			entity_type: entityDetails.entity_type,
			name: entityDetails.name,
			slug: entityDetails.slug,
			parent_id: entityDetails.parent_id,
			parent_name: entityDetails.parent_name,
			parent_slug: entityDetails.parent_slug ?? null,
			metadata: entityDetails.metadata ?? {},
			enabled_classifiers: entityDetails.enabled_classifiers,
			created_at: createdAtIso,
			view_url: viewUrl,
		},
		warnings: warnings.length > 0 ? warnings : undefined,
		next_steps: nextSteps,
	};
}

