1	/**
2	 * Declarative entity-link resolver at event ingestion.
3	 *
4	 * A connector declares `eventKinds[kind].attributions[]` rules. Each attribution
5	 * maps event identifier fields (phone, email, wa_jid, ...) to a target entity.
6	 * The ingestion pipeline:
7	 *   1) Extracts + normalizes identifiers from each event.
8	 *   2) Looks them up in the normalized `entity_identities` table
9	 *      (UNIQUE per (org, namespace, identifier)).
10	 *   3) Links to the matched entity, creates on miss (when autoCreate=true),
11	 *      logs a merge candidate when one event's identifiers resolve to
12	 *      multiple distinct entities.
13	 *   4) Merges declared `traits` onto entities.metadata per behavior.
14	 *
15	 * Never mutates `events.entity_ids` — events stay immutable, JOIN-at-read
16	 * recovers the relationship via entity_identities.
17	 */
18	
19	import { randomBytes } from 'node:crypto';
20	import {
21	  ACL_RESOURCE_TYPE_SLUG,
22	  type EntityIdentitySpec,
23	  type EntityLinkPredicate,
24	  type EntityTraitSpec,
25	  type EventAttributionRule,
26	} from '@lobu/connector-sdk';
27	import { normalizeIdentifier } from '@lobu/connector-sdk/identity-normalize';
28	import { ensureResourceEntityType } from '../authz/acl-resource-type';
29	import { type DbClient, getDb, pgTextArray } from '../db/client';
30	import { normalizeConnectorIdentityValue } from '../identity/connector-identity-modules';
31	import logger from './logger';
32	import { getValueAtPath } from './object-path';
33	import { TtlCache } from './ttl-cache';
34	
35	interface BatchItem {
36	  origin_type?: string;
37	  metadata?: Record<string, unknown>;
38	  title?: string | null;
39	}
40	
41	type ResolvedEventAttributionRule = {
42	  role: EventAttributionRule['role'];
43	  entityType: string;
44	  autoCreate?: boolean;
45	  createWhen?: EntityLinkPredicate;
46	  titlePath?: string;
47	  identities: EntityIdentitySpec[];
48	  traits?: Record<string, EntityTraitSpec>;
49	};
50	
51	interface RuleMap {
52	  [kind: string]: ResolvedEventAttributionRule[];
53	}
54	
55	type EventKindAttributionDefinition = {
56	  attributions?: EventAttributionRule[];
57	};
58	
59	function resolveEventAttributions(
60	  def: EventKindAttributionDefinition | undefined
61	): ResolvedEventAttributionRule[] {
62	  return (def?.attributions ?? []).flatMap((rule) => {
63	    const identities = rule.target.identities;
64	    if (!rule.target.entityType || !Array.isArray(identities) || identities.length === 0) {
65	      return [];
66	    }
67	    return [
68	      {
69	        role: rule.role,
70	        entityType: rule.target.entityType,
71	        autoCreate: rule.autoCreate,
72	        createWhen: rule.target.createWhen,
73	        titlePath: rule.target.titlePath,
74	        identities,
75	        traits: rule.traits,
76	      },
77	    ];
78	  });
79	}
80	
81	const RULES_CACHE_TTL_MS = 60_000;
82	// Per-pod caches — no cross-replica sharing.
83	const rulesCache = new TtlCache<RuleMap>(RULES_CACHE_TTL_MS);
84	const creatorCache = new TtlCache<string | null>(RULES_CACHE_TTL_MS);
85	
86	async function resolveOrgCreator(orgId: string): Promise<string | null> {
87	  return creatorCache.getOrSet(orgId, async () => {
88	    const sql = getDb();
89	    const rows = await sql<{ userId: string }>`
90	      SELECT "userId"
91	      FROM "member"
92	      WHERE "organizationId" = ${orgId}
93	      ORDER BY CASE role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,
94	               "createdAt" ASC
95	      LIMIT 1
96	    `;
97	    return rows.length > 0 ? rows[0].userId : null;
98	  });
99	}
100	
101	function randomSlug(entityType: string): string {
102	  const prefix =
103	    entityType
104	      .replace(/^\$/, '')
105	      .replace(/[^a-z0-9]+/gi, '-')
106	      .toLowerCase() || 'entity';
107	  return `${prefix}-${randomBytes(5).toString('hex')}`;
108	}
109	
110	async function loadEventAttributionRules(params: {
111	  connectorKey: string;
112	  feedKey: string;
113	  orgId: string;
114	}): Promise<RuleMap> {
115	  const cacheKey = `${params.orgId}:${params.connectorKey}:${params.feedKey}`;
116	  return rulesCache.getOrSet(cacheKey, async () => {
117	    const sql = getDb();
118	    const rows = await sql`
119	      SELECT feeds_schema
120	      FROM connector_definitions
121	      WHERE key = ${params.connectorKey}
122	        AND organization_id = ${params.orgId}
123	      LIMIT 1
124	    `;
125	
126	    const result: RuleMap = {};
127	    const feedsSchema = rows[0]?.feeds_schema as Record<string, any> | null | undefined;
128	    const feedDef = feedsSchema?.[params.feedKey];
129	    const eventKinds = feedDef?.eventKinds as Record<string, EventKindAttributionDefinition> | undefined;
130	    if (eventKinds) {
131	      for (const [kind, def] of Object.entries(eventKinds)) {
132	        const resolved = resolveEventAttributions(def);
133	        if (resolved.length > 0) result[kind] = resolved;
134	      }
135	    }
136	    return result;
137	  });
138	}
139	
140	/**
141	 * Load the FIRST attribution rule matching `entityType` (and `role`, when given)
142	 * declared anywhere in the connector's feeds_schema. The live app-webhook path
143	 * resolves an actor without a feed context (a delivery names an event, not a
144	 * feed), and a connector's person attribution is identical across its feeds — so
145	 * any feed's rule serves.
146	 *
147	 * `role` disambiguates when one entity type is targeted by several roles on the
148	 * same kind (e.g. an X DM attributes `person` both `authored_by` and `about`):
149	 * pass the role the caller actually wants ('authored_by' for a webhook actor)
150	 * rather than relying on declaration order.
151	 */
152	export async function loadAttributionRuleByType(params: {
153	  connectorKey: string;
154	  orgId: string;
155	  entityType: string;
156	  role?: EventAttributionRule['role'];
157	}): Promise<ResolvedEventAttributionRule | null> {
158	  const roleKey = params.role ?? '__any__';
159	  const cacheKey = `${params.orgId}:${params.connectorKey}:__bytype__:${params.entityType}:${roleKey}`;
160	  const map = await rulesCache.getOrSet(cacheKey, async () => {
161	    const sql = getDb();
162	    const rows = await sql`
163	      SELECT feeds_schema
164	      FROM connector_definitions
165	      WHERE key = ${params.connectorKey}
166	        AND organization_id = ${params.orgId}
167	      LIMIT 1
168	    `;
169	    const result: RuleMap = {};
170	    const feedsSchema = rows[0]?.feeds_schema as Record<string, any> | null | undefined;
171	    if (feedsSchema) {
172	      for (const feed of Object.values(feedsSchema)) {
173	        const eventKinds = (feed as { eventKinds?: Record<string, EventKindAttributionDefinition> })
174	          ?.eventKinds;
175	        if (!eventKinds) continue;
176	        for (const def of Object.values(eventKinds)) {
177	          const match = resolveEventAttributions(def).find(
178	            (r) =>
179	              r.entityType === params.entityType &&
180	              (params.role === undefined || r.role === params.role),
181	          );
182	          if (match) {
183	            result[params.entityType] = [match];
184	            return result;
185	          }
186	        }
187	      }
188	    }
189	    return result;
190	  });
191	  return map[params.entityType]?.[0] ?? null;
192	}
193	
194	export function clearEntityLinkRulesCache(): void {
195	  rulesCache.clear();
196	  creatorCache.clear();
197	}
198	
199	/**
200	 * A single already-normalized identity ready for lookup/create — the resolved
201	 * counterpart of the declarative {@link EntityIdentitySpec} (which carries an
202	 * `eventPath` to extract FROM an event). The store-only sender path hands these
203	 * in directly, having normalized upstream.
204	 */
205	export type ResolvedIdentity = {
206	  namespace: string;
207	  identifier: string;
208	  matchOnly: boolean;
209	  primary: boolean;
210	};
211	
212	type ExtractedLink = {
213	  identities: ResolvedIdentity[];
214	  traits: Map<string, unknown>;
215	  title: string;
216	};
217	
