3	 * attaches claims without stealing or silently dropping them.
4	 *
5	 * `identities.ts` next door loads entity→claims, which is what the resolution
6	 * policy needs once it already has candidate entities. This module answers the
7	 * question a *writer* has to ask first: "does anything already claim this
8	 * phone?" Without it a create path inserts blindly and mints the duplicate that
9	 * a human then has to review away.
10	 */
11	
12	import { type DbClient, pgTextArray } from "../db/client";
13	import type { ResolutionIdentity } from "./policy";
14	
15	/**
16	 * Map key for one claim. Structural rather than delimiter-joined: `namespace`
17	 * and `identifier` are both free-form, so any single separator lets
18	 * `{ns:"a:b", id:"c"}` collide with `{ns:"a", id:"b:c"}` and one entity's claim
19	 * be read as another's.
20	 */
21	export function identityKey(identity: ResolutionIdentity): string {
22		return JSON.stringify([identity.namespace, identity.identifier]);
23	}
24	
25	/**
26	 * The live entity owning each claim, keyed by {@link identityKey}. A missing
27	 * key means nothing claims it yet.
28	 */
29	export async function findEntitiesByIdentity(
30		db: DbClient,
31		input: { organizationId: string; identities: ResolutionIdentity[] },
32	): Promise<Map<string, number>> {
33		const owners = new Map<string, number>();
34		if (input.identities.length === 0) return owners;
35	
36		// De-dupe before querying: a batch routinely repeats the same identifier.
37		const wanted = new Map<string, ResolutionIdentity>();
38		for (const identity of input.identities) {
39			wanted.set(identityKey(identity), identity);
40		}
41		const namespaces = [...wanted.values()].map((i) => i.namespace);
42		const identifiers = [...wanted.values()].map((i) => i.identifier);
43	
44		const rows = await db<{
45			entity_id: number;
46			namespace: string;
47			identifier: string;
48		}>`
49			SELECT ei.entity_id, ei.namespace, ei.identifier
50			FROM entity_identities ei
51			JOIN entities e ON e.id = ei.entity_id
