anchor='''/** Provenance for a claim written through the tool rather than a connector. */'''
assert s.count(anchor)==1
helper='''/**
 * The existing entity an identity claim resolved to, but ONLY if this caller is
 * allowed to see it — the same gates `handleGet` applies, in the same order.
 *
 * The attach path hands back a PRE-EXISTING record the caller may never have
 * had read access to, so without these an agent with create-but-not-read could
 * submit a known identifier and receive that entity's metadata. Returns null
 * rather than throwing: the caller falls through to create, so the denial does
 * not disclose that the entity exists either.
 */
async function readableAttachTarget(
	entityId: number,
	env: Env,
	ctx: ToolContext,
): Promise<CreatedEntity | null> {
	const entity = await getEntity(entityId, env, ctx);
	if (!entity) return null;
	try {
		await assertEntityReadAllowed(undefined, ctx, entity.entity_type);
	} catch {
		return null;
	}
	if (entity.entity_type === MEMBER_ENTITY_TYPE_SLUG) {
		if (!canSeeMemberList(ctx)) return null;
		if (!canSeeMemberEmail(ctx)) {
			const sql = getDb();
			const rows = await sql`
				SELECT metadata_schema FROM entity_types
				WHERE slug = ${MEMBER_ENTITY_TYPE_SLUG}
				  AND organization_id = ${ctx.organizationId}
				  AND deleted_at IS NULL
				LIMIT 1
			`;
			const memberSchema =
				(rows[0]?.metadata_schema as Record<string, unknown> | null) ?? null;
			return {
				...entity,
				metadata: redactMemberEmail(entity.metadata ?? {}, memberSchema),
			};
		}
	}
	return entity;
}

'''
s=s.replace(anchor, helper+anchor, 1)
io.open(p,'w',encoding='utf-8').write(s)
print('ok')
