/**
 * Plain create for a caller who may not resolve against existing entities.
 * Claims are attached best-effort: one already held by another entity stays
 * with its owner and simply does not attach here. Partial attachment is NOT
 * treated as a lost race, because reconciling would hand back the very entity
 * this caller is not allowed to see.
 */
async function createUnresolvedEntity(input: {
	data: EntityData;
	identities: ResolutionIdentity[];
	env: Env;
	ctx: ToolContext;
	sourceConnector: string;
}): Promise<CreatedEntity> {
